-- Phase 65 coordinates existing Network Governance, Internal Projects/Tasks,
-- Documents, Procurement, Assets, Workforce, Learning, Catalog, Hardware,
-- Fiscal, Finance, Reporting, Incidents and Performance modules.
-- quality: allow-nonconcurrent-index reason=new-empty-store-opening-tables

create schema if not exists store_opening_private;
revoke all on schema store_opening_private from public,anon,authenticated;

alter table public.establishments drop constraint if exists establishments_unit_status_check;
alter table public.establishments add constraint establishments_unit_status_check check(unit_status in('pre_opening','test','active','inactive','temporarily_closed','closed'));
alter table public.establishments add column if not exists test_environment boolean not null default false;
alter table public.establishments add column if not exists production_reporting_enabled boolean not null default true;

alter table public.store_opening_templates add column if not exists business_type text,add column if not exists ownership_type text,add column if not exists store_format text,add column if not exists template_status text not null default 'draft' check(template_status in('draft','approved','retired')),add column if not exists supersedes_id uuid references public.store_opening_templates(id) on delete restrict,add column if not exists definition jsonb not null default '{}';
alter table public.store_opening_projects alter column store_id drop not null;
alter table public.store_opening_projects add column if not exists opportunity_id uuid,add column if not exists project_id uuid references public.internal_projects(id) on delete restrict,add column if not exists target_opening_date date,add column if not exists owner_user_id uuid references auth.users(id) on delete restrict,add column if not exists phase text,add column if not exists readiness_score numeric(5,2),add column if not exists go_live_state text not null default 'pending',add column if not exists go_live_approval_id uuid references public.internal_approvals(id) on delete restrict,add column if not exists ramp_up_started_at timestamptz,add column if not exists completed_at timestamptz;
alter table public.store_opening_projects drop constraint if exists store_opening_projects_status_check;
alter table public.store_opening_projects add constraint store_opening_projects_status_check check(status in('not_started','planning','in_progress','at_risk','ready_for_test','ready_for_launch','ready_for_go_live','active','live','ramp_up','completed','cancelled'));
alter table public.store_opening_projects add constraint store_opening_projects_phase_check check(phase is null or phase in('site','contracts','construction','equipment','systems','hiring','training','catalog','inventory','testing','launch','ramp_up'));
alter table public.store_opening_projects add constraint store_opening_projects_go_live_state_check check(go_live_state in('pending','activating','partially_activated','live','rollback_required','failed'));

create table public.opening_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{opening:view}',brand_ids uuid[] not null default '{}',region_ids uuid[] not null default '{}',project_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.expansion_opportunities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,region_id uuid references public.network_regions(id) on delete set null,opportunity_name text not null,location_reference text,ownership_type text not null check(ownership_type in('company_owned','franchise','joint_venture','other')),stage text not null default 'idea' check(stage in('idea','screening','feasibility','approval','approved','rejected','converted_to_opening_project')),owner_user_id uuid not null references auth.users(id) on delete restrict,estimated_opening_date date,estimated_investment_cents bigint check(estimated_investment_cents is null or estimated_investment_cents>=0),status text not null default 'open' check(status in('open','on_hold','approved','rejected','converted','archived')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.store_opening_projects add constraint store_opening_projects_opportunity_fkey foreign key(opportunity_id) references public.expansion_opportunities(id) on delete restrict;
create table public.store_feasibility_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opportunity_id uuid not null references public.expansion_opportunities(id) on delete restrict,assessment_version integer not null,status text not null default 'draft' check(status in('draft','under_review','approved','rejected','superseded')),assumptions jsonb not null default '[]',revenue_forecast_cents bigint,capex_estimate_cents bigint,opex_estimate_cents bigint,break_even_estimate jsonb,risk_summary jsonb not null default '{}',source_registry jsonb not null default '[]',estimate_label text not null default 'Estimativa — não é garantia',reviewed_by uuid references auth.users(id),approved_by uuid references auth.users(id),approval_id uuid references public.internal_approvals(id) on delete restrict,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(opportunity_id,assessment_version));
create table public.store_opening_template_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_id uuid not null references public.store_opening_templates(id) on delete restrict,version integer not null,definition jsonb not null,calculation_hash text not null,status text not null check(status in('draft','approved','retired')),approved_by uuid references auth.users(id),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(template_id,version));
create table public.opening_template_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_version_id uuid not null references public.store_opening_template_versions(id) on delete cascade,domain text not null,requirement_type text not null,title text not null,config jsonb not null default '{}',critical boolean not null default false,sort_order integer not null default 0,active boolean not null default true);
create table public.store_opening_milestones(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,internal_task_id uuid not null references public.internal_tasks(id) on delete restrict,milestone_key text not null,phase text not null,critical boolean not null default false,target_date date,status text not null default 'pending' check(status in('pending','in_progress','blocked','completed','waived')),completed_at timestamptz,override_approval_id uuid references public.internal_approvals(id),override_reason text,unique(opening_project_id,milestone_key),unique(opening_project_id,internal_task_id));
create table public.opening_readiness_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,domain text not null check(domain in('legal_docs','finance','construction','assets','hardware','internet','suppliers','inventory','workforce','training','catalog','payments','fiscal','operations','testing')),requirement_key text not null,title text not null,state text not null default 'blocked' check(state in('ready','attention','blocked','not_applicable')),required boolean not null default true,weight numeric not null default 1 check(weight>0),source_type text,source_id uuid,reasons jsonb not null default '[]',checked_at timestamptz,updated_at timestamptz not null default now(),unique(opening_project_id,domain,requirement_key));
create table public.opening_readiness_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,score numeric(5,2) not null check(score between 0 and 100),status text not null check(status in('ready','attention','blocked')),composition jsonb not null,critical_blockers jsonb not null default '[]',data_as_of timestamptz not null,created_at timestamptz not null default now());
create table public.store_opening_blockers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.store_opening_projects(id) on delete cascade,blocker_type text not null,severity text not null check(severity in('warning','critical')),source_type text not null,source_id uuid,title text not null,status text not null default 'open' check(status in('open','acknowledged','resolved','accepted','cancelled')),owner_user_id uuid not null references auth.users(id),due_at timestamptz,override_approval_id uuid references public.internal_approvals(id),override_reason text,resolved_at timestamptz,created_at timestamptz not null default now());
create table public.opening_document_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,requirement_key text not null,title text not null,document_id uuid references public.compliance_documents(id) on delete restrict,contract_id uuid references public.contracts(id) on delete restrict,status text not null default 'missing' check(status in('missing','uploaded','under_review','approved','expired','not_applicable')),critical boolean not null default false,expires_before_go_live boolean not null default true,unique(opening_project_id,requirement_key));
create table public.opening_asset_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,requirement_key text not null,asset_type text not null,expected_quantity integer not null check(expected_quantity>=0),received_quantity integer not null default 0 check(received_quantity>=0),asset_ids uuid[] not null default '{}',critical boolean not null default false,status text not null default 'planned' check(status in('planned','ordered','partially_received','received','ready','not_applicable')),unique(opening_project_id,requirement_key));
create table public.store_hardware_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null unique references public.store_opening_projects(id) on delete cascade,profile jsonb not null default '[]',connectivity_checks jsonb not null default '[]',status text not null default 'planned' check(status in('planned','ordered','delivered','paired','tested','ready')),updated_at timestamptz not null default now());
create table public.opening_inventory_plan(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,target_opening_quantity numeric not null check(target_opening_quantity>=0),received_quantity numeric not null default 0 check(received_quantity>=0),status text not null default 'planned' check(status in('planned','ordered','partially_received','received','ready')),purchase_order_id uuid references public.purchase_orders(id) on delete set null,unique(opening_project_id,inventory_item_id));
create table public.opening_staffing_plan(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,role_key text not null,planned_headcount integer not null check(planned_headcount>=0),hired integer not null default 0 check(hired>=0),onboarded integer not null default 0 check(onboarded>=0),trained integer not null default 0 check(trained>=0),scheduled_for_opening integer not null default 0 check(scheduled_for_opening>=0),critical_role boolean not null default false,unique(opening_project_id,role_key));
create table public.store_opening_test_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,name text not null,test_type text not null check(test_type in('operational','uat','dry_run','soft_opening')),owner_user_id uuid not null references auth.users(id),status text not null default 'draft' check(status in('draft','ready','running','passed','failed','blocked')),created_at timestamptz not null default now());
create table public.store_opening_test_cases(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,test_plan_id uuid not null references public.store_opening_test_plans(id) on delete cascade,case_key text not null,title text not null,critical boolean not null default false,status text not null default 'not_run' check(status in('not_run','passed','failed','blocked')),evidence jsonb not null default '{}',transaction_reference text,executed_by uuid references auth.users(id),executed_at timestamptz,override_approval_id uuid references public.internal_approvals(id),override_reason text,unique(test_plan_id,case_key));
create table public.soft_opening_periods(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.store_opening_projects(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,scope jsonb not null default '{}',limited_channels text[] not null default '{}',notes text,status text not null default 'planned' check(status in('planned','active','completed','cancelled')),check(ends_at>starts_at));
create table public.store_go_live_executions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete restrict,store_id uuid not null references public.establishments(id) on delete restrict,state text not null default 'pending' check(state in('pending','activating','partially_activated','live','rollback_required','failed')),approval_id uuid not null references public.internal_approvals(id) on delete restrict,override_approval_id uuid references public.internal_approvals(id),override_reason text,correlation_id uuid not null default gen_random_uuid(),idempotency_key text not null,started_by uuid not null references auth.users(id),started_at timestamptz,completed_at timestamptz,failed_step text,error_message text,created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create unique index store_go_live_one_running_idx on public.store_go_live_executions(opening_project_id) where state in('activating','partially_activated','rollback_required');
create table public.store_go_live_steps(id uuid primary key default gen_random_uuid(),execution_id uuid not null references public.store_go_live_executions(id) on delete cascade,step_key text not null,step_order integer not null,status text not null default 'pending' check(status in('pending','running','completed','failed','compensated','skipped')),idempotency_key text not null,compensatable boolean not null default false,before_state jsonb,after_state jsonb,error_message text,started_at timestamptz,completed_at timestamptz,unique(execution_id,step_key),unique(execution_id,idempotency_key));
create table public.store_ramp_up_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.store_opening_projects(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,starts_at date not null,ends_at date not null,target_goal_ids uuid[] not null default '{}',review_cadence text not null check(review_cadence in('weekly','biweekly','monthly','custom')),owner_user_id uuid not null references auth.users(id),status text not null default 'planned' check(status in('planned','active','completed','cancelled')),check(ends_at>starts_at));
create table public.store_ramp_up_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,ramp_up_plan_id uuid not null references public.store_ramp_up_plans(id) on delete cascade,reviewed_at timestamptz not null,metric_snapshot jsonb not null,target_snapshot jsonb not null,trends jsonb not null default '{}',issues jsonb not null default '[]',actions jsonb not null default '[]',peer_group_reference jsonb,created_by uuid references auth.users(id));
create table public.opening_retrospectives(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null unique references public.store_opening_projects(id) on delete restrict,summary text not null,wins jsonb not null default '[]',issues jsonb not null default '[]',recommendations jsonb not null default '[]',completed_by uuid not null references auth.users(id),completed_at timestamptz not null);
create table public.store_opening_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid references public.store_opening_projects(id) on delete cascade,job_type text not null check(job_type in('readiness','go_live','rollback','ramp_up_snapshot','export','forecast_opening_date')),status text not null default 'pending' check(status in('pending','processing','retrying','completed','failed','dead_letter')),payload jsonb not null default '{}',idempotency_key text not null,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),locked_at timestamptz,locked_by text,result jsonb,error_message text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.store_opening_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,opening_project_id uuid references public.store_opening_projects(id) on delete set null,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,correlation_id uuid,reason text,before_state jsonb,after_state jsonb,created_at timestamptz not null default now());

create table public.fact_expansion_opportunities(opportunity_id uuid primary key,organization_id uuid not null,brand_id uuid,region_id uuid,stage text not null,status text not null,estimated_investment_cents bigint,created_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_store_opening_projects(opening_project_id uuid primary key,organization_id uuid not null,brand_id uuid,region_id uuid,store_id uuid,status text not null,phase text,target_opening_date date,readiness_score numeric,loaded_at timestamptz not null default now());
create table public.fact_opening_milestones(milestone_id uuid primary key,organization_id uuid not null,opening_project_id uuid not null,status text not null,critical boolean not null,target_date date,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_opening_blockers(blocker_id uuid primary key,organization_id uuid not null,opening_project_id uuid not null,severity text not null,status text not null,created_at timestamptz not null,resolved_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_opening_budget(opening_project_id uuid primary key,organization_id uuid not null,budget_id uuid,planned_cents bigint,actual_cents bigint,variance_cents bigint,loaded_at timestamptz not null default now());
create table public.fact_opening_test_results(test_case_id uuid primary key,organization_id uuid not null,opening_project_id uuid not null,status text not null,critical boolean not null,executed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_store_ramp_up(review_id uuid primary key,organization_id uuid not null,store_id uuid not null,reviewed_at timestamptz not null,metric_snapshot jsonb not null,target_snapshot jsonb not null,loaded_at timestamptz not null default now());
create table public.dim_opening_stage(stage text primary key,label text not null);create table public.dim_opening_status(status text primary key,label text not null);create table public.dim_blocker_type(blocker_type text primary key,label text not null);create table public.dim_store_format(store_format text primary key,label text not null);create table public.dim_ownership_type(ownership_type text primary key,label text not null);

create index expansion_opportunity_scope_idx on public.expansion_opportunities(organization_id,brand_id,region_id,stage,updated_at desc);
create index opening_project_scope_idx on public.store_opening_projects(organization_id,brand_id,region_id,status,target_opening_date);
create index opening_readiness_project_idx on public.opening_readiness_checks(opening_project_id,domain,state);
create index opening_blockers_project_idx on public.store_opening_blockers(project_id,severity,status,due_at);
create index opening_jobs_claim_idx on public.store_opening_jobs(status,available_at,created_at) where status in('pending','retrying');
create index opening_audit_scope_idx on public.store_opening_audit_events(organization_id,opening_project_id,created_at desc);

create or replace function store_opening_private.can_access(target_org uuid,target_project uuid default null,requested_permission text default 'opening:view')returns boolean language sql stable security definer set search_path='' as $$select (select auth.uid())is not null and(exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=(select auth.uid())and om.active and om.role in('owner','admin'))or exists(select 1 from public.opening_member_permissions p where p.organization_id=target_org and p.user_id=(select auth.uid())and p.active and(requested_permission=any(p.permissions)or'opening:view_network'=any(p.permissions))and(target_project is null or coalesce(array_length(p.project_ids,1),0)=0 or target_project=any(p.project_ids)))or exists(select 1 from public.store_opening_projects op join public.establishment_members em on em.establishment_id=op.store_id where op.id=target_project and op.organization_id=target_org and em.user_id=(select auth.uid())and em.status='active' and requested_permission='opening:view'));$$;
revoke all on function store_opening_private.can_access(uuid,uuid,text)from public,anon;grant execute on function store_opening_private.can_access(uuid,uuid,text)to authenticated;

do $$declare t text;begin foreach t in array array['opening_member_permissions','expansion_opportunities','store_feasibility_assessments','store_opening_template_versions','opening_template_requirements','store_opening_milestones','opening_readiness_checks','opening_readiness_snapshots','store_opening_blockers','opening_document_requirements','opening_asset_requirements','store_hardware_profiles','opening_inventory_plan','opening_staffing_plan','store_opening_test_plans','store_opening_test_cases','soft_opening_periods','store_go_live_executions','store_go_live_steps','store_ramp_up_plans','store_ramp_up_reviews','opening_retrospectives','store_opening_jobs','store_opening_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','opening_service_'||t,t);end loop;end$$;
do $$declare t text;begin foreach t in array array['fact_expansion_opportunities','fact_store_opening_projects','fact_opening_milestones','fact_opening_blockers','fact_opening_budget','fact_opening_test_results','fact_store_ramp_up','dim_opening_stage','dim_opening_status','dim_blocker_type','dim_store_format','dim_ownership_type'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','opening_service_'||t,t);end loop;end$$;

create or replace function public.claim_store_opening_jobs(requested_worker text,requested_limit integer default 10)returns setof public.store_opening_jobs language plpgsql security definer set search_path='' as $$begin return query update public.store_opening_jobs j set status='processing',locked_at=now(),locked_by=requested_worker,attempts=j.attempts+1 where j.id in(select id from public.store_opening_jobs where status in('pending','retrying')and available_at<=now()order by created_at limit least(greatest(requested_limit,1),50)for update skip locked)returning j.*;end$$;
revoke all on function public.claim_store_opening_jobs(text,integer)from public,anon,authenticated;grant execute on function public.claim_store_opening_jobs(text,integer)to service_role;

create or replace function public.execute_store_go_live(requested_execution_id uuid)returns public.store_go_live_executions language plpgsql security definer set search_path='' as $$declare e public.store_go_live_executions;p public.store_opening_projects;result public.store_go_live_executions;step_key text;begin select * into e from public.store_go_live_executions where id=requested_execution_id for update;if not found then raise exception 'go-live execution not found';end if;if e.state='live'then return e;end if;select * into p from public.store_opening_projects where id=e.opening_project_id for update;if p.store_id is null then raise exception 'pre-opening store required';end if;if not exists(select 1 from public.internal_approvals a where a.id=e.approval_id and a.status='approved'and a.resolved_at is not null)then raise exception 'approved ActionEngine approval required';end if;if exists(select 1 from public.store_opening_blockers b where b.project_id=p.id and b.severity='critical'and b.status not in('resolved','accepted','cancelled'))then raise exception 'critical blockers prevent go-live';end if;if not exists(select 1 from public.opening_readiness_snapshots s where s.opening_project_id=p.id and s.status='ready'order by s.created_at desc limit 1)and e.override_approval_id is null then raise exception 'readiness is not approved';end if;if e.override_approval_id is not null and(not exists(select 1 from public.internal_approvals a where a.id=e.override_approval_id and a.status='approved'and a.resolved_at is not null)or coalesce(btrim(e.override_reason),'')='')then raise exception 'invalid readiness override';end if;if exists(select 1 from public.store_opening_test_cases tc join public.store_opening_test_plans tp on tp.id=tc.test_plan_id where tp.opening_project_id=p.id and tc.critical and tc.status<>'passed'and tc.override_approval_id is null)then raise exception 'critical tests prevent go-live';end if;update public.store_go_live_executions set state='activating',started_at=coalesce(started_at,now())where id=e.id;foreach step_key in array array['readiness','catalog','hardware','payments','fiscal','public_channels','reporting']loop insert into public.store_go_live_steps(execution_id,step_key,step_order,status,idempotency_key,compensatable,started_at,completed_at)values(e.id,step_key,array_position(array['readiness','catalog','hardware','payments','fiscal','public_channels','reporting'],step_key),'completed',e.id::text||':'||step_key,step_key in('catalog','public_channels','reporting'),now(),now())on conflict(execution_id,step_key)do update set status='completed',completed_at=coalesce(public.store_go_live_steps.completed_at,now());end loop;update public.establishments set active=true,unit_status='active',test_environment=false,production_reporting_enabled=true,onboarding_activated_at=coalesce(onboarding_activated_at,now()),updated_at=now()where id=p.store_id;update public.store_opening_projects set status='live',phase='ramp_up',go_live_state='live',ramp_up_started_at=now(),updated_at=now()where id=p.id;update public.store_go_live_executions set state='live',completed_at=now(),failed_step=null,error_message=null where id=e.id returning * into result;return result;end$$;
revoke all on function public.execute_store_go_live(uuid)from public,anon,authenticated;grant execute on function public.execute_store_go_live(uuid)to service_role;
create or replace function public.rollback_store_go_live(requested_execution_id uuid,requested_reason text)returns public.store_go_live_executions language plpgsql security definer set search_path='' as $$declare e public.store_go_live_executions;p public.store_opening_projects;result public.store_go_live_executions;begin if coalesce(btrim(requested_reason),'')=''then raise exception 'rollback reason required';end if;select * into e from public.store_go_live_executions where id=requested_execution_id for update;if not found then raise exception 'execution not found';end if;select * into p from public.store_opening_projects where id=e.opening_project_id for update;update public.establishments set active=false,unit_status='test',test_environment=true,production_reporting_enabled=false,updated_at=now()where id=p.store_id;update public.store_opening_projects set status='at_risk',go_live_state='rollback_required',updated_at=now()where id=p.id;update public.store_go_live_steps set status='compensated',completed_at=now()where execution_id=e.id and status='completed'and compensatable;update public.store_go_live_executions set state='rollback_required',error_message=requested_reason where id=e.id returning * into result;return result;end$$;
revoke all on function public.rollback_store_go_live(uuid,text)from public,anon,authenticated;grant execute on function public.rollback_store_go_live(uuid,text)to service_role;

