alter table public.plans add column if not exists store_opening_enabled boolean not null default false,add column if not exists expansion_pipeline_enabled boolean not null default false,add column if not exists opening_readiness_enabled boolean not null default false,add column if not exists go_live_orchestration_enabled boolean not null default false,add column if not exists opening_ai_assistant_enabled boolean not null default false;

